a:1:{s:10:"custom_css";s:14717:"/* PRODUCTO WOOCOMMERCE - ESTILO PYS GRAFITO PREMIUM COMPLETO */

html,
body.single-product,
body.single-product .site,
body.single-product .site-content,
body.single-product .content-area,
body.single-product .site-main,
body.single-product main,
body.single-product #page,
body.single-product .elementor,
body.single-product .elementor-section,
body.single-product .elementor-container,
body.single-product .elementor-widget-container {
  background:
    radial-gradient(circle at 8% 8%, rgba(0, 229, 196, 0.10), transparent 30%),
    radial-gradient(circle at 92% 12%, rgba(247, 0, 122, 0.09), transparent 34%),
    radial-gradient(circle at 50% 90%, rgba(255, 255, 255, 0.035), transparent 38%),
    linear-gradient(135deg, #0D0F10 0%, #101417 38%, #151515 68%, #111111 100%) !important;
}

body.single-product {
  color: #F5F5F2 !important;
}

selector {
  color: #F5F5F2;
  font-family: "Inter", "Helvetica Neue", Arial, sans-serif;
  background:
    radial-gradient(circle at 8% 8%, rgba(0, 229, 196, 0.10), transparent 30%),
    radial-gradient(circle at 92% 12%, rgba(247, 0, 122, 0.09), transparent 34%),
    linear-gradient(135deg, #0D0F10 0%, #101417 42%, #151515 100%) !important;
}

/* Fondo general del producto */
selector .product,
selector .woocommerce div.product,
body.single-product .site-main,
body.single-product .content-area {
  background:
    radial-gradient(circle at 8% 8%, rgba(0, 229, 196, 0.10), transparent 30%),
    radial-gradient(circle at 92% 12%, rgba(247, 0, 122, 0.09), transparent 34%),
    radial-gradient(circle at 50% 90%, rgba(255, 255, 255, 0.035), transparent 38%),
    linear-gradient(135deg, #0D0F10 0%, #101417 38%, #151515 68%, #111111 100%) !important;
}

/* Contenedor principal del producto */
selector .product {
  position: relative;
  overflow: hidden;
  padding: clamp(28px, 4vw, 52px) !important;
  border-radius: 34px;
  background:
    radial-gradient(circle at 14% 18%, rgba(0, 229, 196, 0.12), transparent 34%),
    radial-gradient(circle at 88% 74%, rgba(247, 0, 122, 0.10), transparent 34%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.09), rgba(255, 255, 255, 0.035)),
    rgba(16, 20, 23, 0.88) !important;
  border: 1px solid rgba(255, 255, 255, 0.15);
  box-shadow:
    0 30px 78px rgba(0, 0, 0, 0.52),
    0 0 42px rgba(0, 229, 196, 0.10),
    0 0 36px rgba(247, 0, 122, 0.08);
}

/* Breadcrumb */
selector .woocommerce-breadcrumb,
selector .woocommerce-breadcrumb a {
  color: #BFC4C2 !important;
  font-size: 14px;
  text-decoration: none !important;
}

selector .woocommerce-breadcrumb a:hover {
  color: #00E5C4 !important;
}

/* Imagen producto */
selector div.product div.images,
selector .woocommerce-product-gallery {
  border-radius: 32px;
  overflow: hidden;
  background:
    radial-gradient(circle at 50% 45%, rgba(0, 229, 196, 0.12), transparent 46%),
    radial-gradient(circle at 75% 80%, rgba(247, 0, 122, 0.09), transparent 36%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.075), rgba(255, 255, 255, 0.035)),
    rgba(13, 15, 16, 0.88) !important;
  border: 1px solid rgba(255, 255, 255, 0.14);
  box-shadow:
    0 26px 70px rgba(0, 0, 0, 0.46),
    0 0 34px rgba(0, 229, 196, 0.09);
  padding: 22px;
}

selector div.product div.images img,
selector .woocommerce-product-gallery img {
  border-radius: 24px;
  object-fit: contain;
  background: #FFFFFF !important;
  filter: drop-shadow(0 24px 34px rgba(0, 0, 0, 0.35));
}

/* Lupa de galería */
selector .woocommerce-product-gallery__trigger {
  background: rgba(13, 15, 16, 0.86) !important;
  color: #FFFFFF !important;
  border: 1px solid rgba(0, 229, 196, 0.32);
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.38);
}

/* Columna de información */
selector div.product div.summary,
selector .summary.entry-summary {
  padding: clamp(24px, 3vw, 42px) !important;
  border-radius: 32px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.085), rgba(255, 255, 255, 0.035)),
    rgba(16, 20, 23, 0.78) !important;
  border: 1px solid rgba(255, 255, 255, 0.14);
  box-shadow:
    0 24px 62px rgba(0, 0, 0, 0.42),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(14px);
}

/* Título */
selector .product_title,
selector h1.product_title {
  margin-bottom: 18px !important;
  color: #FFFFFF !important;
  font-family: "Optima", "Optima LT Std", "Candara", "Segoe UI", Arial, sans-serif !important;
  font-size: clamp(2rem, 4vw, 3.6rem) !important;
  line-height: 1.05 !important;
  letter-spacing: -0.055em;
  font-weight: 400 !important;
}

/* Precio */
selector .price,
selector .price .amount,
selector p.price {
  color: #00E5C4 !important;
  font-size: clamp(1.45rem, 2.5vw, 2rem) !important;
  font-weight: 900 !important;
  letter-spacing: -0.03em;
}

/* Disponibilidad / stock */
selector .stock,
selector p.stock,
selector .out-of-stock {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin: 12px 0 18px !important;
  padding: 9px 15px !important;
  border-radius: 999px;
  background: rgba(247, 0, 122, 0.14) !important;
  border: 1px solid rgba(247, 0, 122, 0.32);
  color: #FFFFFF !important;
  font-weight: 800 !important;
  letter-spacing: 0.03em;
}

/* Texto de resumen */
selector .woocommerce-product-details__short-description,
selector .woocommerce-product-details__short-description p,
selector .summary.entry-summary p {
  color: #BFC4C2 !important;
  line-height: 1.72;
}

/* Cantidad */
selector .quantity input.qty {
  width: 64px !important;
  height: 48px !important;
  border-radius: 12px !important;
  border: 1px solid rgba(255, 255, 255, 0.18) !important;
  background: rgba(255, 255, 255, 0.08) !important;
  color: #FFFFFF !important;
  font-weight: 900;
}

/* Botón carrito */
selector button.single_add_to_cart_button,
selector .single_add_to_cart_button,
selector .button {
  min-height: 50px !important;
  padding: 14px 24px !important;
  border-radius: 999px !important;
  border: 1px solid transparent !important;
  background: linear-gradient(135deg, #00E5C4 0%, #F7007A 100%) !important;
  color: #111111 !important;
  -webkit-text-fill-color: #111111 !important;
  font-size: 0.82rem !important;
  font-weight: 950 !important;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  box-shadow:
    0 18px 42px rgba(0, 0, 0, 0.34),
    0 0 34px rgba(0, 229, 196, 0.16),
    0 0 28px rgba(247, 0, 122, 0.12);
  transition: transform 0.28s ease, box-shadow 0.28s ease, filter 0.28s ease;
}

selector button.single_add_to_cart_button:hover,
selector .single_add_to_cart_button:hover,
selector .button:hover {
  transform: translateY(-3px);
  filter: saturate(1.08);
  box-shadow:
    0 22px 52px rgba(0, 0, 0, 0.46),
    0 0 42px rgba(0, 229, 196, 0.20),
    0 0 36px rgba(247, 0, 122, 0.16);
}

/* Botón deshabilitado / agotado */
selector button.single_add_to_cart_button.disabled,
selector button.single_add_to_cart_button:disabled,
selector .button.disabled,
selector .button:disabled {
  background: rgba(255, 255, 255, 0.10) !important;
  color: #BFC4C2 !important;
  -webkit-text-fill-color: #BFC4C2 !important;
  border: 1px solid rgba(255, 255, 255, 0.18) !important;
  box-shadow: none !important;
  opacity: 1 !important;
  cursor: not-allowed !important;
}

/* Categorías, etiquetas y marca */
selector .product_meta {
  margin-top: 30px;
  padding-top: 22px;
  border-top: 1px solid rgba(255, 255, 255, 0.14);
  color: #BFC4C2 !important;
  line-height: 1.7;
}

selector .product_meta span,
selector .product_meta a {
  color: #BFC4C2 !important;
  text-decoration: none !important;
}

selector .product_meta a {
  color: #F7007A !important;
  font-weight: 700;
}

selector .product_meta a:hover {
  color: #00E5C4 !important;
}

/* Tabs / descripción */
selector .woocommerce-tabs {
  margin-top: 44px !important;
  padding: clamp(24px, 3vw, 38px);
  border-radius: 32px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.035)),
    rgba(16, 20, 23, 0.82) !important;
  border: 1px solid rgba(255, 255, 255, 0.14);
  box-shadow: 0 22px 56px rgba(0, 0, 0, 0.40);
}

selector .woocommerce-tabs ul.tabs {
  border-bottom: 1px solid rgba(255, 255, 255, 0.14) !important;
}

selector .woocommerce-tabs ul.tabs::before {
  border-bottom: 1px solid rgba(255, 255, 255, 0.14) !important;
}

selector .woocommerce-tabs ul.tabs li {
  border-radius: 999px !important;
  background: rgba(255, 255, 255, 0.07) !important;
  border: 1px solid rgba(255, 255, 255, 0.14) !important;
}

selector .woocommerce-tabs ul.tabs li::before,
selector .woocommerce-tabs ul.tabs li::after {
  display: none !important;
}

selector .woocommerce-tabs ul.tabs li a {
  color: #FFFFFF !important;
  font-weight: 900 !important;
}

selector .woocommerce-tabs ul.tabs li.active {
  background: linear-gradient(135deg, rgba(0, 229, 196, 0.22), rgba(247, 0, 122, 0.16)) !important;
  border-color: rgba(0, 229, 196, 0.34) !important;
}

selector .woocommerce-Tabs-panel,
selector .woocommerce-Tabs-panel p,
selector .woocommerce-Tabs-panel li {
  color: #BFC4C2 !important;
  line-height: 1.75;
}

/* Títulos internos */
selector .woocommerce-Tabs-panel h2,
selector .related.products h2,
selector .upsells.products h2 {
  color: #FFFFFF !important;
  font-family: "Optima", "Optima LT Std", "Candara", "Segoe UI", Arial, sans-serif !important;
  font-weight: 400 !important;
  letter-spacing: -0.04em;
}

/* Listas dentro de descripción */
selector .woocommerce-Tabs-panel ul,
selector .woocommerce-Tabs-panel ol {
  padding-left: 20px;
}

selector .woocommerce-Tabs-panel strong,
selector .woocommerce-Tabs-panel b {
  color: #FFFFFF !important;
}

/* Productos relacionados */
selector .related.products,
selector .upsells.products {
  margin-top: 50px;
}

selector .related.products ul.products li.product,
selector .upsells.products ul.products li.product,
selector ul.products li.product {
  padding: 20px !important;
  border-radius: 28px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.035)),
    rgba(16, 20, 23, 0.84) !important;
  border: 1px solid rgba(255, 255, 255, 0.14);
  box-shadow: 0 20px 48px rgba(0, 0, 0, 0.36);
}

selector ul.products li.product img {
  border-radius: 20px;
  background: #FFFFFF !important;
  padding: 8px;
}

selector ul.products li.product .woocommerce-loop-product__title {
  color: #FFFFFF !important;
  font-weight: 900;
}

selector ul.products li.product .price {
  color: #00E5C4 !important;
}

/* Enlaces generales */
selector a {
  color: #00E5C4;
}

selector a:hover {
  color: #F7007A;
}

/* Formularios / variaciones si aparecen */
selector table.variations,
selector table.variations td,
selector table.variations th {
  color: #F5F5F2 !important;
  border-color: rgba(255, 255, 255, 0.14) !important;
}

selector select,
selector input,
selector textarea {
  background: rgba(255, 255, 255, 0.08) !important;
  color: #FFFFFF !important;
  border: 1px solid rgba(255, 255, 255, 0.18) !important;
  border-radius: 14px !important;
}

selector select:focus,
selector input:focus,
selector textarea:focus {
  outline: none !important;
  border-color: rgba(0, 229, 196, 0.60) !important;
  box-shadow: 0 0 0 3px rgba(0, 229, 196, 0.12) !important;
}

/* Mensajes WooCommerce */
selector .woocommerce-message,
selector .woocommerce-info,
selector .woocommerce-error {
  border-radius: 20px !important;
  background: rgba(16, 20, 23, 0.92) !important;
  color: #F5F5F2 !important;
  border: 1px solid rgba(255, 255, 255, 0.14) !important;
}

/* Responsive */
@media (max-width: 768px) {
  html,
  body.single-product,
  body.single-product .site,
  body.single-product .site-content,
  body.single-product .content-area,
  body.single-product .site-main,
  body.single-product main,
  body.single-product #page,
  body.single-product .elementor,
  body.single-product .elementor-section,
  body.single-product .elementor-container,
  body.single-product .elementor-widget-container {
    background:
      radial-gradient(circle at 8% 8%, rgba(0, 229, 196, 0.09), transparent 32%),
      radial-gradient(circle at 92% 18%, rgba(247, 0, 122, 0.08), transparent 34%),
      linear-gradient(135deg, #0D0F10 0%, #101417 48%, #151515 100%) !important;
  }

  selector .product {
    padding: 22px 16px !important;
    border-radius: 26px;
  }

  selector div.product div.images,
  selector .woocommerce-product-gallery,
  selector div.product div.summary,
  selector .summary.entry-summary {
    border-radius: 24px;
  }

  selector .product_title,
  selector h1.product_title {
    font-size: clamp(1.9rem, 9vw, 2.8rem) !important;
    text-align: center;
  }

  selector .price,
  selector p.price {
    text-align: center;
  }

  selector form.cart {
    display: flex !important;
    flex-direction: column;
    gap: 12px;
    align-items: stretch;
  }

  selector .quantity input.qty {
    width: 100% !important;
  }

  selector button.single_add_to_cart_button,
  selector .single_add_to_cart_button {
    width: 100% !important;
  }

  selector .product_meta {
    text-align: center;
  }

  selector .woocommerce-tabs {
    padding: 22px 16px;
    border-radius: 24px;
  }

  selector .woocommerce-tabs ul.tabs {
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 0 !important;
  }

  selector .woocommerce-tabs ul.tabs li {
    width: 100%;
    text-align: center;
    margin: 0 !important;
  }

  selector .related.products ul.products,
  selector .upsells.products ul.products,
  selector ul.products {
    display: grid !important;
    grid-template-columns: 1fr !important;
    gap: 18px !important;
  }
}

@media (max-width: 420px) {
  selector .product {
    padding: 18px 12px !important;
  }

  selector div.product div.images,
  selector .woocommerce-product-gallery {
    padding: 14px;
  }

  selector div.product div.summary,
  selector .summary.entry-summary {
    padding: 20px 16px !important;
  }

  selector .product_title,
  selector h1.product_title {
    font-size: clamp(1.7rem, 10vw, 2.45rem) !important;
  }

  selector button.single_add_to_cart_button,
  selector .single_add_to_cart_button,
  selector .button {
    font-size: 0.74rem !important;
    letter-spacing: 0.045em;
  }
}";}
